function parseOptions(
  value?: string,
): string[] {
  if (!value) {
    return [];
  }

  try {
    const parsed = JSON.parse(value);

    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed
      .filter(
        (item): item is string =>
          typeof item === "string",
      )
      .map((item) => item.trim())
      .filter(Boolean);
  } catch {
    return [];
  }
}

function learningStageIndex(action: string): number {
  switch (action) {
    case "teach":
    case "diagnose":
      return 0;

    case "practice":
    case "scaffold":
    case "remediate":
      return 1;

    case "transfer_check":
      return 2;

    case "reassess":
    case "retention_check":
      return 3;

    case "advance":
    case "complete":
      return 4;

    default:
      return 0;
  }
}
function actionLabel(
  action: string,
): string {
  switch (action) {
    case "teach":
      return "Let's learn this together.";

    case "practice":
      return "Let's practise what you have learned.";

    case "scaffold":
      return "Let's work through this step by step.";

    case "remediate":
      return "Let's look at this another way.";

    case "reassess":
      return "Let's check what you understand now.";

    case "diagnose":
      return "Let's find out what you already know.";

    case "retention_check":
      return "Let's see what you remember.";

    case "transfer_check":
      return "Let's see if you can use it somewhere new.";

    case "advance":
      return "You are ready for the next step.";

    case "complete":
      return "You have completed this learning sequence.";

    default:
      return "Let's keep learning.";
  }
}

function buttonLabel(
  action: string,
): string {
  switch (action) {
    case "teach":
      return "Continue learning";

    case "practice":
      return "Continue practising";

    case "scaffold":
      return "Continue";

    case "remediate":
      return "Continue";

    case "reassess":
      return "Try again";

    case "diagnose":
      return "Start";

    case "retention_check":
      return "Continue";

    case "transfer_check":
      return "Continue";

    case "advance":
      return "Continue to the next step";

    default:
      return "Continue";
  }
}

function feedbackTitle(
  outcome: string,
): string {
  switch (outcome) {
    case "correct":
      return "Correct";

    case "incorrect":
      return "Not quite";

    case "partial":
      return "Partly correct";

    default:
      return "Answer recorded";
  }
}

function feedbackMessage(
  outcome: string,
): string {
  switch (outcome) {
    case "correct":
      return "Well done. FILUMIRE has recorded this as successful evidence.";

    case "incorrect":
      return "That answer was not correct. FILUMIRE will use this evidence to decide what you need next.";

    case "partial":
      return "You have part of it right. FILUMIRE will use this evidence to guide what comes next.";

    default:
      return "Your response has been recorded.";
  }
}

